import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

triu_matmul_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE 32

__global__ void triu_matmul_kernel(const float* __restrict__ A,
                                    const float* __restrict__ B,
                                    float* __restrict__ C,
                                    int N) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    int blockRow = blockIdx.y * TILE;
    int blockCol = blockIdx.x * TILE;

    int row = blockRow + threadIdx.y;
    int col = blockCol + threadIdx.x;

    float sum = 0.0f;

    // Only compute if this block could contain non-zero upper-triangular contributions
    if (blockCol + TILE - 1 >= blockRow) {
        int numTiles = (N + TILE - 1) / TILE;
        for (int t = 0; t < numTiles; t++) {
            int k0 = t * TILE;

            // If entire k-tile has k < blockRow, A[row,k] is zero for all rows in this block
            if (k0 + TILE - 1 < blockRow) continue;
            // If entire k-tile has k > blockCol+TILE-1, B[k,col] is zero for all cols in this block
            if (k0 > blockCol + TILE - 1) break;

            int aCol = k0 + threadIdx.x;
            int bRow = k0 + threadIdx.y;

            As[threadIdx.y][threadIdx.x] = (row < N && aCol < N) ? A[row * N + aCol] : 0.0f;
            Bs[threadIdx.y][threadIdx.x] = (bRow < N && col < N) ? B[bRow * N + col] : 0.0f;

            __syncthreads();

            #pragma unroll
            for (int k = 0; k < TILE; k++) {
                sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
            }

            __syncthreads();
        }
    }

    if (row < N && col < N) {
        C[row * N + col] = (row <= col) ? sum : 0.0f;
    }
}

torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");

    A = A.contiguous();
    B = B.contiguous();

    int N = A.size(0);

    auto C = torch::empty({N, N}, A.options());

    dim3 block(TILE, TILE);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);

    triu_matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

triu_matmul_cpp_source = r"""
torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

triu_matmul_module = load_inline(
    name="triu_matmul_module",
    cpp_sources=triu_matmul_cpp_source,
    cuda_sources=triu_matmul_source,
    functions=["triu_matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A * B) for upper
    triangular matrices using a custom fused CUDA kernel that skips
    computation for tiles guaranteed to be zero due to the triangular
    structure, and masks the lower triangle of the output.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.triu_matmul = triu_matmul_module

    def forward(self, A, B):
        return self.triu_matmul.triu_matmul_cuda(A, B)


N = 4096

def get_inputs():
    A = torch.triu(torch.rand(N, N)).cuda()
    B = torch.triu(torch.rand(N, N)).cuda()
    return [A, B]

def get_init_inputs():
    return []

